CREATE TABLE IF NOT EXISTS users (id CHAR(36) PRIMARY KEY, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, full_name VARCHAR(120) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS profiles (id CHAR(36) PRIMARY KEY, user_id CHAR(36) NOT NULL UNIQUE, full_name VARCHAR(120) DEFAULT '', monthly_income DECIMAL(15,2) DEFAULT 0, currency VARCHAR(10) DEFAULT 'INR', risk_tolerance VARCHAR(20) DEFAULT 'moderate', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, CONSTRAINT fk_profiles_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS expenses (id CHAR(36) PRIMARY KEY, user_id CHAR(36) NOT NULL, amount DECIMAL(15,2) NOT NULL, category VARCHAR(80) NOT NULL DEFAULT 'other', description VARCHAR(500) DEFAULT '', date DATE NOT NULL, type VARCHAR(20) DEFAULT 'expense', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX idx_exp_user_date(user_id,date), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS debts (id CHAR(36) PRIMARY KEY,user_id CHAR(36) NOT NULL,name VARCHAR(160) NOT NULL,type VARCHAR(30) DEFAULT 'personal',principal DECIMAL(15,2) DEFAULT 0,interest_rate DECIMAL(8,3) DEFAULT 0,tenure_months INT DEFAULT 12,emi_amount DECIMAL(15,2) DEFAULT 0,remaining_balance DECIMAL(15,2) DEFAULT 0,start_date DATE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS emergency_fund (id CHAR(36) PRIMARY KEY,user_id CHAR(36) NOT NULL UNIQUE,target_months INT DEFAULT 6,current_corpus DECIMAL(15,2) DEFAULT 0,monthly_expenses DECIMAL(15,2) DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS insurance (id CHAR(36) PRIMARY KEY,user_id CHAR(36) NOT NULL,name VARCHAR(160) NOT NULL,type VARCHAR(30) DEFAULT 'life',coverage_amount DECIMAL(15,2) DEFAULT 0,premium_amount DECIMAL(15,2) DEFAULT 0,premium_frequency VARCHAR(20) DEFAULT 'yearly',start_date DATE,maturity_date DATE,notes TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS investments (id CHAR(36) PRIMARY KEY,user_id CHAR(36) NOT NULL,name VARCHAR(160) NOT NULL,type VARCHAR(40) DEFAULT 'mutual_fund',invested_amount DECIMAL(15,2) DEFAULT 0,current_value DECIMAL(15,2) DEFAULT 0,expected_return DECIMAL(8,3) DEFAULT 8,start_date DATE,notes TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS goals (id CHAR(36) PRIMARY KEY,user_id CHAR(36) NOT NULL,name VARCHAR(160) NOT NULL,target_amount DECIMAL(15,2) DEFAULT 0,current_amount DECIMAL(15,2) DEFAULT 0,target_date DATE,category VARCHAR(40) DEFAULT 'general',color VARCHAR(20) DEFAULT '#3c3c3c',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS income_sources (id CHAR(36) PRIMARY KEY,user_id CHAR(36) NOT NULL,name VARCHAR(160) NOT NULL,amount DECIMAL(15,2) DEFAULT 0,frequency VARCHAR(30) DEFAULT 'monthly',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS fire_plans (id CHAR(36) PRIMARY KEY,user_id CHAR(36) NOT NULL UNIQUE,current_age INT DEFAULT 30,target_fire_age INT DEFAULT 50,annual_income DECIMAL(15,2) DEFAULT 0,salary_growth_rate DECIMAL(8,3) DEFAULT 5,annual_expenses DECIMAL(15,2) DEFAULT 0,current_investments DECIMAL(15,2) DEFAULT 0,expected_return DECIMAL(8,3) DEFAULT 8,withdrawal_rate DECIMAL(8,3) DEFAULT 4,inflation_rate DECIMAL(8,3) DEFAULT 6,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS budget_plans (id CHAR(36) PRIMARY KEY,user_id CHAR(36) NOT NULL UNIQUE,salary DECIMAL(15,2) DEFAULT 0,additional_income DECIMAL(15,2) DEFAULT 0,housing DECIMAL(15,2) DEFAULT 0,loans_emis DECIMAL(15,2) DEFAULT 0,utilities DECIMAL(15,2) DEFAULT 0,food DECIMAL(15,2) DEFAULT 0,education DECIMAL(15,2) DEFAULT 0,insurance DECIMAL(15,2) DEFAULT 0,investments DECIMAL(15,2) DEFAULT 0,savings DECIMAL(15,2) DEFAULT 0,other DECIMAL(15,2) DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS family_info (id CHAR(36) PRIMARY KEY,user_id CHAR(36) NOT NULL UNIQUE,emergency_contacts JSON NOT NULL,insurance_policies JSON NOT NULL,bank_details JSON NOT NULL,investment_details JSON NOT NULL,property_info JSON NOT NULL,documents JSON NOT NULL,identity_details JSON NOT NULL,liabilities JSON NOT NULL,will_info JSON NOT NULL,power_of_attorney JSON NOT NULL,emergency_info JSON NOT NULL,digital_accounts JSON NOT NULL,important_dates JSON NOT NULL,funeral_wishes JSON NOT NULL,family_tree JSON NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
